from __future__ import annotations

import unicodedata
import unittest


class NfcNormalizationTest(unittest.TestCase):
    def test_nfc_string_unchanged(self) -> None:
        from ledgerlock.format import normalize_key

        self.assertEqual(normalize_key("\u00e9"), "\u00e9")

    def test_nfd_collapses_to_nfc(self) -> None:
        from ledgerlock.format import normalize_key

        self.assertEqual(normalize_key("e\u0301"), "\u00e9")

    def test_nfc_and_nfd_byte_identical(self) -> None:
        from ledgerlock.format import normalize_key

        nfc = normalize_key("\u00e9")
        nfd = normalize_key("e\u0301")
        self.assertEqual(nfc, nfd)
        self.assertEqual(nfc.encode("utf-8"), nfd.encode("utf-8"))

    def test_against_stdlib_unicodedata(self) -> None:
        from ledgerlock.format import normalize_key

        samples = ["", "abc", "\u00e9", "e\u0301", "\u1e9b\u0323", "\u00fc", "u\u0308"]
        for s in samples:
            self.assertEqual(normalize_key(s), unicodedata.normalize("NFC", s))


if __name__ == "__main__":
    unittest.main()

